/* file.close — explicit close that surfaces delayed write errors.
   Marks the file as closed so z_t4716_destroy skips a second close. */
static z_t4767_t z_t4716_close(z_t4716_t* p);
static z_t4767_t z_t4716_close(z_t4716_t* p) {
    z_t4767_t result = {0};
    if (!p || !p->f1) {
        result.tag = Z_T4767_TAG_1;
        result.data = NULL;
        return result;
    }
#if defined(_WIN32)
    int rc = z_win_close(p->f0);
    int e = (int)GetLastError();
#else
    int rc = close(p->f0);
    int e = errno;
#endif
    p->f1 = false;
    return z_io_wrap_null_Result(rc, e);
}


/* file.write — write all bytes from `src`. Loops on short writes;
   retries on EINTR. Returns total bytes written on success.
   `src` is a listview (layout: length, data*), matching byteview. */
static z_t4760_t z_t4716_write(
    z_t4716_t* f, z_t108_t src
);
static z_t4760_t z_t4716_write(
    z_t4716_t* f, z_t108_t src
) {
    uint64_t total = 0;
    while (total < src.length) {
#if defined(_WIN32)
        if (z_win_console_write(f->f0, (const char*)src.data + total, src.length - total, 0)) {
            total = src.length;
            break;
        }
        int64_t n = z_win_write(f->f0, src.data + total, src.length - total);
        if (n < 0) return z_io_u64_err((int)GetLastError());
#else
        int64_t n = write(f->f0, src.data + total, src.length - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            return z_io_u64_err(errno);
        }
#endif
        total += (uint64_t)n;
    }
    return z_io_u64_ok(total);
}


/* file.read — read up to `max` bytes, appending to `buf`.
   Grows the list capacity as needed. Returns actual bytes read
   (0 indicates EOF); retries on EINTR. The loop breaks out so the body
   ends in its return -- c2mir miscompiles a struct return otherwise. */
static z_t4760_t z_t4716_read(
    z_t4716_t* f, z_t4720_t* buf, uint64_t max
);
static z_t4760_t z_t4716_read(
    z_t4716_t* f, z_t4720_t* buf, uint64_t max
) {
    if (buf->capacity < buf->length + max) {
        uint64_t newcap = buf->length + max;
        buf->data = (uint8_t*)z_xrealloc(buf->data, newcap);
        buf->capacity = newcap;
    }
    int64_t n;
#if defined(_WIN32)
    n = z_win_read(f->f0, buf->data + buf->length, max);
    if (n < 0) return z_io_u64_err((int)GetLastError());
#else
    for (;;) {
        n = read(f->f0, buf->data + buf->length, max);
        if (n >= 0) break;
        if (errno != EINTR) return z_io_u64_err(errno);
    }
#endif
    buf->length += (uint64_t)n;
    return z_io_u64_ok((uint64_t)n);
}


/* file.seek — reposition the fd head, 64-bit on every system. Maps
   seekorigin to the matching whence constant. Returns the new absolute
   position measured from the start of the file. */
static z_t4760_t z_t4716_seek(
    z_t4716_t* f, int64_t off, z_t4776_t origin
);
static z_t4760_t z_t4716_seek(
    z_t4716_t* f, int64_t off, z_t4776_t origin
) {
    int whence;
    switch (origin) {
        case Z_T4776_TAG_0:   whence = SEEK_SET; break;
        case Z_T4776_TAG_1: whence = SEEK_CUR; break;
        case Z_T4776_TAG_2:     whence = SEEK_END; break;
        default:                       whence = SEEK_SET; break;
    }
#if defined(_WIN32)
    int64_t pos = z_win_seek(f->f0, off, whence);
    if (pos < 0) return z_io_u64_err((int)GetLastError());
#else
    off_t pos = lseek(f->f0, (off_t)off, whence);
    if (pos < 0) return z_io_u64_err(errno);
#endif
    return z_io_u64_ok((uint64_t)pos);
}


/* file.flush — no-op for raw file descriptors (POSIX write goes
   directly to the kernel, no userspace buffer to drain). Exists
   so file satisfies the `writer` protocol signature. */
static z_t4767_t z_t4716_flush(z_t4716_t* f);
static z_t4767_t z_t4716_flush(z_t4716_t* f) {
    (void)f;
    z_t4767_t result = {0};
    result.tag = Z_T4767_TAG_1;
    result.data = NULL;
    return result;
}


