/* os.monotonicMillis -- milliseconds on the monotonic clock. Only
   differences are meaningful (the epoch is arbitrary, typically boot).
   Infallible: CLOCK_MONOTONIC cannot fail on a supported platform, nor
   QueryPerformanceCounter on Windows. */
#include <time.h>
static int64_t z_os_monotonicMillis(void);
static int64_t z_os_monotonicMillis(void) {
#if defined(_WIN32)
    LARGE_INTEGER f;
    LARGE_INTEGER c;
    QueryPerformanceFrequency(&f);
    QueryPerformanceCounter(&c);
    return (int64_t)(c.QuadPart / f.QuadPart) * 1000 + (int64_t)((c.QuadPart % f.QuadPart) * 1000 / f.QuadPart);
#else
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (int64_t)ts.tv_sec * 1000 + (int64_t)(ts.tv_nsec / 1000000);
#endif
}
/* os.pid -- getpid (GetCurrentProcessId on Windows). A pid fits in
   int32_t on every supported platform (Linux caps at 4_194_304 by
   default; Windows' are multiples of 4 below 2^26 in practice). */
static int32_t z_os_pid(void);
static int32_t z_os_pid(void) {
#if defined(_WIN32)
    return (int32_t)GetCurrentProcessId();
#else
    return (int32_t)getpid();
#endif
}
/* os.sleepMillis -- suspend the calling thread for ms milliseconds.
   Restarts after EINTR so the full duration always elapses; Windows'
   Sleep is not interrupted. */
#include <time.h>
static void z_os_sleepMillis(int64_t ms);
static void z_os_sleepMillis(int64_t ms) {
    if (ms <= 0) return;
#if defined(_WIN32)
    while (ms > 0) {
        DWORD part = ms > 0x7fffffff ? 0x7fffffff : (DWORD)ms;
        Sleep(part);
        ms -= (int64_t)part;
    }
#else
    struct timespec req;
    req.tv_sec = (time_t)(ms / 1000);
    req.tv_nsec = (long)(ms % 1000) * 1000000L;
    while (nanosleep(&req, &req) != 0 && errno == EINTR) {
    }
#endif
}
/* os.tempDir -- $TMPDIR, else /tmp; on Windows GetTempPathW (which reads
   %TMP%, %TEMP%, %USERPROFILE%, then the Windows directory), a native path.
   A trailing separator is dropped unless the path is a root. */
static z_t64_t z_os_tempDir(void);
static z_t64_t z_os_tempDir(void) {
#if defined(_WIN32)
    wchar_t w[MAX_PATH + 2];
    DWORD n = GetTempPathW(MAX_PATH + 1, w);
    char* u = NULL;
    size_t un = 0;
    if (n > 0 && n <= MAX_PATH + 1) u = z_win_utf8(w, (int)n, &un);
    if (u == NULL) return z_t64_new("C:\\Windows\\Temp");
    while (un > 1 && (u[un - 1] == '\\' || u[un - 1] == '/') && !(un == 3 && u[1] == ':')) u[--un] = '\0';
    z_t64_t out = z_t64_new(u);
    free(u);
    return out;
#else
    const char* t = getenv("TMPDIR");
    if (t == NULL || t[0] == '\0') t = "/tmp";
    size_t n = strlen(t);
    while (n > 1 && t[n - 1] == '/') n--;
    z_t64_t out = z_t64_create((uint64_t)n);
    z_t64_append(&out, t, (uint64_t)n);
    return out;
#endif
}
/* z_os_spawn_start -- start argv as a child, the start os.spawn and
   os.spawnAsync share. stdout->outPath, stderr->errPath (each created or
   truncated); an empty out/err path inherits the parent's stream, and empty
   out+err inherits stdin too (else stdin is the null device). A non-empty cwd
   is the child's working directory. Answers 0 with the child's pid and the
   OS's handle on it, or the OS error code: the redirections could not be
   opened, the directory could not be entered, or the program could not be
   started.

   The redirection files are opened in the parent before the child starts, so
   the child's cwd cannot change their resolution, and no other child started
   meanwhile inherits them: a child sees only its three standard streams.

   POSIX: posix_spawnp (argv[0] resolved via PATH), which unlike fork is safe in
   a program that runs threads -- the child runs no code of ours between its
   start and the exec; the redirections are opened close-on-exec and handed
   over as 0/1/2 by file actions (dup2 clears close-on-exec on the copy). The
   handle is a pidfd, -1 on a kernel without them.

   Windows: CreateProcessW with a command line quoted so CommandLineToArgvW
   (and the C runtime) split it back into argv exactly; argv[0] is resolved
   through PATH, a name without an extension tried with .exe and .com; a .bat
   or .cmd is refused (ERROR_BAD_EXE_FORMAT) -- cmd.exe runs those, by its own
   quoting rules. The three standard handles are duplicated inheritable and
   are the only handles the child inherits (PROC_THREAD_ATTRIBUTE_HANDLE_LIST).
   The handle is the process handle. argv element buffers are NUL-terminated
   and borrowed. */
#if defined(_WIN32)
/* append `s` to the command line `w`, quoted when it must be */
static size_t z_os_win_quote(wchar_t* w, size_t at, const wchar_t* s, int force) {
    int plain = !force && s[0] != 0;
    for (const wchar_t* c = s; *c != 0 && plain; c++) {
        if (*c == L' ' || *c == L'\t' || *c == L'\n' || *c == L'\v' || *c == L'"') plain = 0;
    }
    if (plain) {
        for (const wchar_t* c = s; *c != 0; c++) w[at++] = *c;
        return at;
    }
    w[at++] = L'"';
    size_t bs = 0;
    for (const wchar_t* c = s;; c++) {
        if (*c == L'\\') {
            bs++;
            continue;
        }
        if (*c == 0) {
            /* backslashes before the closing quote are doubled */
            for (size_t k = 0; k < bs * 2; k++) w[at++] = L'\\';
            break;
        }
        if (*c == L'"') {
            for (size_t k = 0; k < bs * 2 + 1; k++) w[at++] = L'\\';
        } else {
            for (size_t k = 0; k < bs; k++) w[at++] = L'\\';
        }
        bs = 0;
        w[at++] = *c;
    }
    w[at++] = L'"';
    return at;
}

static int z_os_win_is_file(const wchar_t* p) {
    DWORD a = GetFileAttributesW(p);
    return a != INVALID_FILE_ATTRIBUTES && !(a & FILE_ATTRIBUTE_DIRECTORY);
}

/* the program argv[0] names: as written when it holds a separator, else the
   first PATH directory that has it; either way tried as written when it has
   an extension, else with .exe, then .com. NULL with the last error set when
   there is none. */
static wchar_t* z_os_win_find_program(const wchar_t* name) {
    size_t n = wcslen(name);
    int has_sep = wcschr(name, L'\\') != NULL || wcschr(name, L'/') != NULL || (n >= 2 && name[1] == L':');
    const wchar_t* base = name;
    for (const wchar_t* c = name; *c != 0; c++) if (*c == L'\\' || *c == L'/' || *c == L':') base = c + 1;
    int has_ext = wcschr(base, L'.') != NULL;
    const wchar_t* exts[] = { L"", L".exe", L".com" };
    int first = has_ext ? 0 : 1;
    int last = has_ext ? 0 : 2;
    wchar_t* path = NULL;
    DWORD pn = 0;
    if (!has_sep) {
        pn = GetEnvironmentVariableW(L"PATH", NULL, 0);
        if (pn > 0) {
            path = (wchar_t*)z_xmalloc((size_t)pn * sizeof(wchar_t));
            if (GetEnvironmentVariableW(L"PATH", path, pn) == 0) path[0] = 0;
        }
    }
    const wchar_t* dir = has_sep ? L"" : (path != NULL ? path : L"");
    wchar_t* found = NULL;
    for (;;) {
        const wchar_t* end = has_sep ? dir : wcschr(dir, L';');
        size_t dn = has_sep ? 0 : (end != NULL ? (size_t)(end - dir) : wcslen(dir));
        if (has_sep || dn > 0) {
            for (int k = first; k <= last && found == NULL; k++) {
                size_t cap = dn + 1 + n + 5;
                wchar_t* cand = (wchar_t*)z_xmalloc(cap * sizeof(wchar_t));
                size_t at = 0;
                for (size_t i = 0; i < dn; i++) cand[at++] = dir[i];
                if (dn > 0 && cand[at - 1] != L'\\' && cand[at - 1] != L'/') cand[at++] = L'\\';
                for (size_t i = 0; i < n; i++) cand[at++] = name[i];
                for (const wchar_t* e = exts[k]; *e != 0; e++) cand[at++] = *e;
                cand[at] = 0;
                if (z_os_win_is_file(cand)) found = cand; else free(cand);
            }
        }
        if (found != NULL || has_sep || end == NULL) break;
        dir = end + 1;
    }
    free(path);
    if (found == NULL) SetLastError(ERROR_FILE_NOT_FOUND);
    return found;
}

/* an inheritable copy of a standard handle, or of the null device when this
   process has none; NULL on failure */
static HANDLE z_os_win_inheritable(HANDLE h) {
    HANDLE dup = NULL;
    if (h == NULL || h == INVALID_HANDLE_VALUE) {
        SECURITY_ATTRIBUTES sa = { sizeof(SECURITY_ATTRIBUTES), NULL, TRUE };
        dup = CreateFileW(L"NUL", GENERIC_READ | GENERIC_WRITE, FILE_SHARE_READ | FILE_SHARE_WRITE, &sa, OPEN_EXISTING, 0, NULL);
        return dup == INVALID_HANDLE_VALUE ? NULL : dup;
    }
    if (!DuplicateHandle(GetCurrentProcess(), h, GetCurrentProcess(), &dup, 0, TRUE, DUPLICATE_SAME_ACCESS)) return NULL;
    return dup;
}

/* a redirection file, opened for writing and inheritable */
static HANDLE z_os_win_redirect(z_t84_t path) {
    wchar_t* w = z_win_path(path.data, path.size);
    if (w == NULL) return NULL;
    SECURITY_ATTRIBUTES sa = { sizeof(SECURITY_ATTRIBUTES), NULL, TRUE };
    HANDLE h = CreateFileW(w, GENERIC_WRITE, FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, &sa, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL);
    DWORD e = GetLastError();
    free(w);
    SetLastError(e);
    return h == INVALID_HANDLE_VALUE ? NULL : h;
}
#else
#include <spawn.h>
extern char** environ;
#endif

static int z_os_spawn_start(
    const z_t604_t* argv, z_t84_t cwd, z_t84_t outPath,
    z_t84_t errPath, int32_t* pid_out, int64_t* handle_out
);
static int z_os_spawn_start(
    const z_t604_t* argv, z_t84_t cwd, z_t84_t outPath,
    z_t84_t errPath, int32_t* pid_out, int64_t* handle_out
) {
    *pid_out = 0;
    *handle_out = -1;
    int inherit_out = (outPath.size == 0);
    int inherit_err = (errPath.size == 0);
    int inherit_in = (inherit_out && inherit_err);
#if defined(_WIN32)
    if (argv->length == 0) return ERROR_INVALID_PARAMETER;
    /* the arguments as UTF-16, and the program they name */
    wchar_t** wargs = (wchar_t**)z_xmalloc(argv->length * sizeof(wchar_t*));
    size_t line_cap = 1;
    int bad = 0;
    for (uint64_t i = 0; i < argv->length; i++) {
        wargs[i] = z_win_wide(argv->data[i].data, argv->data[i].size);
        if (wargs[i] == NULL) {
            bad = 1;
            wargs[i] = z_win_wide("", 0);
        }
        line_cap += wcslen(wargs[i]) * 2 + 3;
    }
    int rc = 0;
    wchar_t* program = NULL;
    if (bad) {
        rc = ERROR_NO_UNICODE_TRANSLATION;
    } else if (wcschr(wargs[0], L'"') != NULL) {
        rc = ERROR_INVALID_NAME;
    } else {
        program = z_os_win_find_program(wargs[0]);
        if (program == NULL) {
            rc = (int)GetLastError();
        } else {
            size_t pl = wcslen(program);
            const wchar_t* ext = pl >= 4 ? program + pl - 4 : L"";
            if (_wcsicmp(ext, L".bat") == 0 || _wcsicmp(ext, L".cmd") == 0) rc = ERROR_BAD_EXE_FORMAT;
        }
    }
    wchar_t* line = NULL;
    if (rc == 0) {
        line = (wchar_t*)z_xmalloc(line_cap * sizeof(wchar_t));
        size_t at = z_os_win_quote(line, 0, wargs[0], 1);
        for (uint64_t i = 1; i < argv->length; i++) {
            line[at++] = L' ';
            at = z_os_win_quote(line, at, wargs[i], 0);
        }
        line[at] = 0;
    }
    for (uint64_t i = 0; i < argv->length; i++) free(wargs[i]);
    free(wargs);
    HANDLE hin = NULL;
    HANDLE hout = NULL;
    HANDLE herr = NULL;
    wchar_t* wcwd = NULL;
    if (rc == 0) {
        hout = inherit_out ? z_os_win_inheritable(GetStdHandle(STD_OUTPUT_HANDLE)) : z_os_win_redirect(outPath);
        if (hout == NULL) rc = (int)GetLastError();
    }
    if (rc == 0) {
        herr = inherit_err ? z_os_win_inheritable(GetStdHandle(STD_ERROR_HANDLE)) : z_os_win_redirect(errPath);
        if (herr == NULL) rc = (int)GetLastError();
    }
    if (rc == 0) {
        hin = z_os_win_inheritable(inherit_in ? GetStdHandle(STD_INPUT_HANDLE) : NULL);
        if (hin == NULL) rc = (int)GetLastError();
    }
    if (rc == 0 && cwd.size > 0) {
        wcwd = z_win_path(cwd.data, cwd.size);
        if (wcwd == NULL) {
            rc = (int)GetLastError();
        } else {
            DWORD a = GetFileAttributesW(wcwd);
            if (a == INVALID_FILE_ATTRIBUTES) rc = (int)GetLastError();
            else if (!(a & FILE_ATTRIBUTE_DIRECTORY)) rc = ERROR_DIRECTORY;
        }
    }
    LPPROC_THREAD_ATTRIBUTE_LIST attrs = NULL;
    HANDLE inherit[3] = { hin, hout, herr };
    if (rc == 0) {
        SIZE_T asize = 0;
        InitializeProcThreadAttributeList(NULL, 1, 0, &asize);
        attrs = (LPPROC_THREAD_ATTRIBUTE_LIST)z_xmalloc(asize);
        if (!InitializeProcThreadAttributeList(attrs, 1, 0, &asize)
            || !UpdateProcThreadAttribute(attrs, 0, PROC_THREAD_ATTRIBUTE_HANDLE_LIST, inherit, sizeof inherit, NULL, NULL)) {
            rc = (int)GetLastError();
        }
    }
    if (rc == 0) {
        STARTUPINFOEXW si;
        memset(&si, 0, sizeof si);
        si.StartupInfo.cb = sizeof si;
        si.StartupInfo.dwFlags = STARTF_USESTDHANDLES;
        si.StartupInfo.hStdInput = hin;
        si.StartupInfo.hStdOutput = hout;
        si.StartupInfo.hStdError = herr;
        si.lpAttributeList = attrs;
        PROCESS_INFORMATION pi;
        if (CreateProcessW(program, line, NULL, NULL, TRUE, CREATE_UNICODE_ENVIRONMENT | EXTENDED_STARTUPINFO_PRESENT,
                           NULL, wcwd, &si.StartupInfo, &pi)) {
            CloseHandle(pi.hThread);
            *pid_out = (int32_t)pi.dwProcessId;
            *handle_out = (int64_t)(intptr_t)pi.hProcess;
        } else {
            rc = (int)GetLastError();
        }
    }
    if (attrs != NULL) {
        DeleteProcThreadAttributeList(attrs);
        free(attrs);
    }
    if (hin != NULL) CloseHandle(hin);
    if (hout != NULL) CloseHandle(hout);
    if (herr != NULL) CloseHandle(herr);
    free(wcwd);
    free(line);
    free(program);
    return rc;
#else
    if (argv->length == 0) return EINVAL;
    char** c_argv = (char**)z_xmalloc((argv->length + 1) * sizeof(char*));
    for (uint64_t i = 0; i < argv->length; i++) {
        c_argv[i] = argv->data[i].data;
    }
    c_argv[argv->length] = NULL;
    char* cwd_c = z_sv_to_cstr(cwd);
    int rc = 0;
    int out_fd = -1;
    int err_fd = -1;
    int null_fd = -1;
    if (!inherit_out) {
        char* out_c = z_sv_to_cstr(outPath);
        out_fd = open(out_c, O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC, 0644);
        if (out_fd < 0) rc = errno;
        free(out_c);
    }
    if (rc == 0 && !inherit_err) {
        char* err_c = z_sv_to_cstr(errPath);
        err_fd = open(err_c, O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC, 0644);
        if (err_fd < 0) rc = errno;
        free(err_c);
    }
    if (rc == 0 && !inherit_in) {
        null_fd = open("/dev/null", O_RDONLY | O_CLOEXEC);
        if (null_fd < 0) rc = errno;
    }
    if (rc == 0) {
        posix_spawn_file_actions_t fa;
        posix_spawn_file_actions_init(&fa);
        if (cwd.size > 0) rc = posix_spawn_file_actions_addchdir_np(&fa, cwd_c);
        if (rc == 0 && !inherit_in) rc = posix_spawn_file_actions_adddup2(&fa, null_fd, 0);
        if (rc == 0 && !inherit_out) rc = posix_spawn_file_actions_adddup2(&fa, out_fd, 1);
        if (rc == 0 && !inherit_err) rc = posix_spawn_file_actions_adddup2(&fa, err_fd, 2);
        pid_t child = -1;
        if (rc == 0) rc = posix_spawnp(&child, c_argv[0], &fa, NULL, c_argv, environ);
        posix_spawn_file_actions_destroy(&fa);
        if (rc == 0) {
            *pid_out = (int32_t)child;
#ifdef SYS_pidfd_open
            int pfd = (int)syscall(SYS_pidfd_open, child, 0);
            if (pfd >= 0) *handle_out = (int64_t)pfd;
#endif
        }
    }
    if (out_fd >= 0) close(out_fd);
    if (err_fd >= 0) close(err_fd);
    if (null_fd >= 0) close(null_fd);
    free(cwd_c);
    free(c_argv);
    return rc;
#endif
}
/* os.spawn -- start argv as a child (z_os_spawn_start: PATH resolution,
   redirections, cwd) and wait for it. Returns the child's exit status; 128 +
   signo for a child a signal ended; 127 on exec/setup failure; 124 if
   timeoutSecs > 0 and the child outlived it (killed). timeoutSecs <= 0 waits
   forever.

   The timeout waits on the child's own handle -- its pidfd, polled; on
   Windows its process handle -- so it touches no process-wide state (no
   signal handler, no alarm) and another thread's spawn is not disturbed. A
   kernel without pidfd_open (ENOSYS) is polled with WNOHANG every 10ms
   instead. */
#include <time.h>
#if !defined(_WIN32)
static int32_t z_os_spawn_status(int wst) {
    if (WIFEXITED(wst)) return (int32_t)WEXITSTATUS(wst);
    if (WIFSIGNALED(wst)) return 128 + (int32_t)WTERMSIG(wst);
    return 127;
}
#endif
static int32_t z_os_spawn(
    z_t604_t* argv, z_t84_t cwd, z_t84_t outPath,
    z_t84_t errPath, int32_t timeoutSecs
);
static int32_t z_os_spawn(
    z_t604_t* argv, z_t84_t cwd, z_t84_t outPath,
    z_t84_t errPath, int32_t timeoutSecs
) {
    int32_t pid = 0;
    int64_t handle = -1;
    if (z_os_spawn_start(argv, cwd, outPath, errPath, &pid, &handle) != 0) return 127;
#if defined(_WIN32)
    HANDLE h = (HANDLE)(intptr_t)handle;
    DWORD budget = INFINITE;
    if (timeoutSecs > 0) budget = timeoutSecs < 4000000 ? (DWORD)timeoutSecs * 1000 : 4000000000u;
    DWORD w = WaitForSingleObject(h, budget);
    int32_t status = 127;
    if (w == WAIT_TIMEOUT) {
        TerminateProcess(h, 137);
        WaitForSingleObject(h, INFINITE);
        status = 124;
    } else {
        DWORD code = 0;
        if (w == WAIT_OBJECT_0 && GetExitCodeProcess(h, &code)) status = (int32_t)code;
    }
    CloseHandle(h);
    return status;
#else
    int pfd = (int)handle;
    int wst = 0;
    int32_t status = 127;
    if (timeoutSecs <= 0) {
        for (;;) {
            if (waitpid(pid, &wst, 0) >= 0) {
                status = z_os_spawn_status(wst);
                break;
            }
            if (errno != EINTR) break;
        }
        if (pfd >= 0) close(pfd);
        return status;
    }
    int64_t budget = (int64_t)timeoutSecs * 1000;
    if (pfd >= 0) {
        struct pollfd p = { pfd, POLLIN, 0 };
        struct timespec t0;
        clock_gettime(CLOCK_MONOTONIC, &t0);
        int ready = 0;
        for (;;) {
            struct timespec t1;
            clock_gettime(CLOCK_MONOTONIC, &t1);
            int64_t spent = (int64_t)(t1.tv_sec - t0.tv_sec) * 1000
                          + (int64_t)(t1.tv_nsec - t0.tv_nsec) / 1000000;
            if (spent >= budget) break;
            int r = poll(&p, 1, (int)(budget - spent));
            if (r > 0) { ready = 1; break; }
            if (r < 0 && errno != EINTR) break;
        }
        close(pfd);
        if (!ready) {
            kill(pid, SIGKILL);
            while (waitpid(pid, &wst, 0) < 0 && errno == EINTR) {}
            return 124;
        }
        while (waitpid(pid, &wst, 0) < 0) {
            if (errno != EINTR) return 127;
        }
        return z_os_spawn_status(wst);
    }
    for (int64_t waited = 0; ; waited += 10) {
        pid_t r = waitpid(pid, &wst, WNOHANG);
        if (r == pid) return z_os_spawn_status(wst);
        if (r < 0 && errno != EINTR) return 127;
        if (waited >= budget) break;
        struct timespec ts = { 0, 10 * 1000000L };
        nanosleep(&ts, NULL);
    }
    kill(pid, SIGKILL);
    while (waitpid(pid, &wst, 0) < 0 && errno == EINTR) {}
    return 124;
#endif
}
/* Shared by tcc.available and tcc.compileToExe: the libtcc entry points and
   the dlopen (LoadLibraryW on Windows) that finds them.

   libtcc is LOADED, never linked. That is a licence requirement, not a
   preference -- tinycc is LGPL-2.1 inside a permissive tree -- and
   `make static-tcc-guard` fails the build if any tcc symbol reaches a
   binary. So the names below are strings, resolved at the point of use;
   nothing here creates a link-time dependency, and a zc built without a
   tcc beside it is a zc that reports 127 rather than one that fails to
   start.

   The library lives in <tccDir> -- libtcc.so, or libtcc.dll on Windows --
   the same directory that holds the runtime payload tcc_set_lib_path needs.
   One directory, one answer. */
#if defined(_WIN32)
#define Z_TCC_LIB_FILE "\\libtcc.dll"
#else
#include <dlfcn.h>
#define Z_TCC_LIB_FILE "/libtcc.so"
#endif
typedef struct TCCState z_tcc_State;
typedef void z_tcc_ErrorFunc(void* opaque, const char* msg);

typedef struct {
    void* handle;
    z_tcc_State* (*nw)(void);
    void (*del)(z_tcc_State*);
    void (*set_lib_path)(z_tcc_State*, const char*);
    void (*set_error_func)(z_tcc_State*, void*, z_tcc_ErrorFunc*);
    int (*set_options)(z_tcc_State*, const char*);
    int (*set_output_type)(z_tcc_State*, int);
    int (*add_file)(z_tcc_State*, const char*);
    int (*add_library)(z_tcc_State*, const char*);
    int (*output_file)(z_tcc_State*, const char*);
} z_tcc_api_t;

#define Z_TCC_OUTPUT_EXE 2
#define Z_TCC_OUTPUT_OBJ 3

/* diagnostics go to stderr verbatim, so a program reports the same text
   whichever mode built it. */
static void z_tcc_on_error(void* opaque, const char* msg) {
    (void)opaque;
    fprintf(stderr, "%s\n", msg);
}

static char* z_tcc_lib_path(z_t84_t tccDir) {
    char* dir = z_sv_to_cstr(tccDir);
    size_t n = strlen(dir);
    char* p = (char*)z_xmalloc(n + sizeof(Z_TCC_LIB_FILE));
    memcpy(p, dir, n);
    memcpy(p + n, Z_TCC_LIB_FILE, sizeof(Z_TCC_LIB_FILE));
    free(dir);
    return p;
}

/* the address of `name` in the loaded library, NULL when it has none */
static void* z_tcc_sym(void* handle, const char* name) {
#if defined(_WIN32)
    /* ISO C has no conversion from a function pointer to void*: the bytes are
       copied, which is what dlsym's own result is on the other systems */
    FARPROC p = GetProcAddress((HMODULE)handle, name);
    void* r;
    memcpy(&r, &p, sizeof r);
    return r;
#else
    return dlsym(handle, name);
#endif
}

/* 1 when every entry point resolved. A partial load is a failed load: a
   libtcc missing one of these is not one this code can drive. */
static void z_tcc_close(z_tcc_api_t* a);

static int z_tcc_open(z_tcc_api_t* a, z_t84_t tccDir) {
    memset(a, 0, sizeof(*a));
    char* path = z_tcc_lib_path(tccDir);
#if defined(_WIN32)
    wchar_t* wpath = z_win_path(path, strlen(path));
    a->handle = wpath ? (void*)LoadLibraryW(wpath) : NULL;
    free(wpath);
#else
    a->handle = dlopen(path, RTLD_NOW | RTLD_LOCAL);
#endif
    free(path);
    if (!a->handle) return 0;
    *(void**)&a->nw = z_tcc_sym(a->handle, "tcc_new");
    *(void**)&a->del = z_tcc_sym(a->handle, "tcc_delete");
    *(void**)&a->set_lib_path = z_tcc_sym(a->handle, "tcc_set_lib_path");
    *(void**)&a->set_error_func = z_tcc_sym(a->handle, "tcc_set_error_func");
    *(void**)&a->set_options = z_tcc_sym(a->handle, "tcc_set_options");
    *(void**)&a->set_output_type = z_tcc_sym(a->handle, "tcc_set_output_type");
    *(void**)&a->add_file = z_tcc_sym(a->handle, "tcc_add_file");
    *(void**)&a->add_library = z_tcc_sym(a->handle, "tcc_add_library");
    *(void**)&a->output_file = z_tcc_sym(a->handle, "tcc_output_file");
    if (a->nw && a->del && a->set_lib_path && a->set_error_func
        && a->set_options && a->set_output_type && a->add_file
        && a->add_library && a->output_file) {
        return 1;
    }
    z_tcc_close(a);
    return 0;
}

static void z_tcc_close(z_tcc_api_t* a) {
#if defined(_WIN32)
    if (a->handle) FreeLibrary((HMODULE)a->handle);
#else
    if (a->handle) dlclose(a->handle);
#endif
    a->handle = NULL;
}

/* tcc.compileToExe -- compile `csrc` and link it to the executable `exe`,
   in this process, through libtcc loaded from `tccDir`.

   The result is a file on disk (TCC_OUTPUT_EXE), never a run in memory:
   in-process buys the fast COMPILE, and the program still executes as its
   own child, so exit codes, signals and the leak corpus are unaffected and
   a crashing program cannot take zc down with it.

   `tccDir` is also handed to tcc_set_lib_path -- tcc's runtime payload is
   fixed when tcc is configured, so a relocated one cannot resolve even
   stddef.h until it is told. `cflags` is parsed by tcc itself (the same
   spelling as the command line); `libs` are the `-l` names the emitted C
   declared, with -lm appended the way the spawned path appends it; `objs`
   are object files linked in after the source.

   Returns 0 on success, 1 when tcc rejected the program or the link
   failed, and 127 when libtcc could not be loaded -- the code os.spawn
   already uses for "could not run the compiler", so the driver reports
   both through one path rather than growing a second. */
static int32_t z_tcc_compileToExe(
    z_t84_t csrc, z_t84_t exe, z_t84_t tccDir,
    bool release, z_t84_t cflags, const z_t604_t* libs,
    const z_t604_t* objs
);
static int32_t z_tcc_compileToExe(
    z_t84_t csrc, z_t84_t exe, z_t84_t tccDir,
    bool release, z_t84_t cflags, const z_t604_t* libs,
    const z_t604_t* objs
) {
    z_tcc_api_t a;
    if (!z_tcc_open(&a, tccDir)) return 127;

    z_tcc_State* s = a.nw();
    if (!s) {
        z_tcc_close(&a);
        return 127;
    }
    a.set_error_func(s, NULL, z_tcc_on_error);

    char* dir_c = z_sv_to_cstr(tccDir);
    a.set_lib_path(s, dir_c);
    free(dir_c);

    int32_t rc = 0;
    /* -g matches the spawned path's debug default; tcc has one optimisation
       level, so --release changes nothing here beyond dropping -g. */
    if (!release && a.set_options(s, "-g") == -1) rc = 1;

    if (rc == 0 && cflags.size > 0) {
        char* cf = z_sv_to_cstr(cflags);
        if (a.set_options(s, cf) == -1) rc = 1;
        free(cf);
    }
    if (rc == 0 && a.set_output_type(s, Z_TCC_OUTPUT_EXE) == -1) rc = 1;

    if (rc == 0) {
        char* src_c = z_sv_to_cstr(csrc);
        if (a.add_file(s, src_c) == -1) rc = 1;
        free(src_c);
    }
    if (rc == 0) {
        for (uint64_t i = 0; i < objs->length; i++) {
            if (a.add_file(s, objs->data[i].data) == -1) {
                rc = 1;
                break;
            }
        }
    }
    if (rc == 0) {
        for (uint64_t i = 0; i < libs->length; i++) {
            if (a.add_library(s, libs->data[i].data) == -1) {
                rc = 1;
                break;
            }
        }
    }
#if !defined(_WIN32)
    /* Windows has no libm: its math is the C runtime's */
    if (rc == 0 && a.add_library(s, "m") == -1) rc = 1;
#endif

    if (rc == 0) {
        char* exe_c = z_sv_to_cstr(exe);
        if (a.output_file(s, exe_c) == -1) rc = 1;
        free(exe_c);
    }

    a.del(s);
    z_tcc_close(&a);
    return rc;
}

/* tcc.compileToObject -- compile `csrc` to the object file `obj`, in this
   process, through libtcc loaded from `tccDir` (TCC_OUTPUT_OBJ). `cflags` is
   parsed by tcc itself, the -D defines among them. Codes as compileToExe's:
   0 on success, 1 when tcc rejected the source, 127 when libtcc could not be
   loaded. */
static int32_t z_tcc_compileToObject(
    z_t84_t csrc, z_t84_t obj, z_t84_t tccDir,
    z_t84_t cflags
);
static int32_t z_tcc_compileToObject(
    z_t84_t csrc, z_t84_t obj, z_t84_t tccDir,
    z_t84_t cflags
) {
    z_tcc_api_t a;
    if (!z_tcc_open(&a, tccDir)) return 127;

    z_tcc_State* s = a.nw();
    if (!s) {
        z_tcc_close(&a);
        return 127;
    }
    a.set_error_func(s, NULL, z_tcc_on_error);

    char* dir_c = z_sv_to_cstr(tccDir);
    a.set_lib_path(s, dir_c);
    free(dir_c);

    int32_t rc = 0;
    if (cflags.size > 0) {
        char* cf = z_sv_to_cstr(cflags);
        if (a.set_options(s, cf) == -1) rc = 1;
        free(cf);
    }
    if (rc == 0 && a.set_output_type(s, Z_TCC_OUTPUT_OBJ) == -1) rc = 1;
    if (rc == 0) {
        char* src_c = z_sv_to_cstr(csrc);
        if (a.add_file(s, src_c) == -1) rc = 1;
        free(src_c);
    }
    if (rc == 0) {
        char* obj_c = z_sv_to_cstr(obj);
        if (a.output_file(s, obj_c) == -1) rc = 1;
        free(obj_c);
    }

    a.del(s);
    z_tcc_close(&a);
    return rc;
}

